import{_ as r,o as a,c as n,ah as t}from"./chunks/framework.Yx0DUrwu.js";const h=JSON.parse('{"title":"inferCNV 教程","description":"","frontmatter":{},"headers":[],"relativePath":"tools/infercnv/index.md","filePath":"tools/infercnv/index.md","lastUpdated":1787830595000}'),i={name:"tools/infercnv/index.md"};function o(s,e,l,c,f,p){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="infercnv-教程" tabindex="-1">inferCNV 教程 <a class="header-anchor" href="#infercnv-教程" aria-label="Permalink to &quot;inferCNV 教程&quot;">​</a></h1><p>inferCNV 是常用于从单细胞 RNA-seq 表达矩阵中推断大尺度拷贝数变异的工具，特别常见于肿瘤单细胞分析。它通过基因在染色体上的位置，对表达信号按染色体区域平滑，比较目标细胞与参考正常细胞的表达偏移，从而推断疑似 CNV 模式。</p><p>它的核心用途不是精确替代 DNA 层面的 CNV 检测，而是帮助区分恶性细胞和非恶性参考细胞，或观察肿瘤亚克隆结构。结论应尽量与 WGS/WES、拷贝数实验或肿瘤标志基因互相验证。</p><div class="path-grid"><a href="/tools/infercnv/cnv-workflow"><strong>CNV 推断流程</strong><span>准备计数矩阵、细胞注释、基因排序文件和参考细胞群，并运行 inferCNV。</span></a><a href="/biology/central-dogma-omics"><strong>基因组与转录组关系</strong><span>理解表达推断 CNV 的假设和局限。</span></a><a href="/tools/common-tools/"><strong>同类工具</strong><span>CopyKAT, HoneyBADGER, CONICSmat 等也常用于肿瘤 CNV 推断。</span></a><a href="/references/"><strong>参考资料</strong><span>查看 inferCNV 官方文档和肿瘤单细胞分析实践资料。</span></a></div><h2 id="适合场景" tabindex="-1">适合场景 <a class="header-anchor" href="#适合场景" aria-label="Permalink to &quot;适合场景&quot;">​</a></h2><div class="check-grid"><article><strong>肿瘤上皮细胞识别</strong><span>比较上皮样细胞和免疫/基质参考细胞，识别疑似恶性细胞。</span></article><article><strong>肿瘤亚群结构</strong><span>观察不同细胞群是否共享 CNV 模式或呈现亚克隆差异。</span></article><article><strong>质量控制辅助</strong><span>检查疑似恶性细胞群是否有一致的染色体臂级别信号。</span></article><article><strong>论文结果解释</strong><span>许多肿瘤单细胞论文会用 inferCNV 图展示恶性细胞与非恶性细胞的差异。</span></article></div><h2 id="资料来源" tabindex="-1">资料来源 <a class="header-anchor" href="#资料来源" aria-label="Permalink to &quot;资料来源&quot;">​</a></h2><ul><li><a href="https://github.com/broadinstitute/infercnv" target="_blank" rel="noreferrer">inferCNV documentation</a></li><li><a href="https://github.com/broadinstitute/infercnv/wiki" target="_blank" rel="noreferrer">inferCNV wiki</a></li><li><a href="https://github.com/broadinstitute/infercnv/wiki" target="_blank" rel="noreferrer">Trinity CTAT inferCNV page</a></li></ul>',8)])])}const g=r(i,[["render",o]]);export{h as __pageData,g as default};
